#include <map>

class stringx
{
  int data[4];

public:
  stringx(const stringx&);
  ~stringx();
};

bool operator<(const stringx&, const stringx&);

class entity_track_tree;

struct ett_node
{
  bool stored;
  int ref;
  unsigned int aram_id;
  unsigned int offset;
  unsigned int size;
  entity_track_tree* ett;
};

class ett_manager
{
  typedef std::map<stringx, ett_node> ett_map_t;
  typedef std::map<stringx, ett_node>::iterator ett_map_itr_t;

public:
  ~ett_manager();

private:
  void ett_free(void*);

  ett_map_t ett_map;
  char* bin1_addr;
  char* bin2_addr;
  int resident_anms;
  int resident_alloc_size;
  int max_resident_anms;
  int max_resident_alloc_size;
  int cache_hits;
  int cache_misses;
};

ett_manager::~ett_manager()
{
  ett_map_itr_t itr = ett_map.begin();
  for (; itr != ett_map.end(); itr++)
  {
    stringx name = (*itr).first;
    ett_node& node = (*itr).second;
    if (!node.stored && node.ett != 0)
      ett_free(node.ett);
  }

  ett_map.clear();
}
